import { ZodError } from "zod";
import { logError } from "@/server/utils/logger";

export class ApiError extends Error {
  constructor(
    message: string,
    public readonly status = 400,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

// UUID v1-v8, any case. Your previous regex only allowed versions 1-8
// in the version nibble but rejected some valid v4 variants generated by
// gen_random_uuid(); this is the standard "any UUID" check.
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function assertUuid(value: string, label: string): void {
  if (typeof value !== "string" || !UUID_RE.test(value)) {
    throw new ApiError(`${label} must be a valid UUID`, 400);
  }
}

export interface JsonError {
  error: string;
  details?: unknown;
}

export function jsonOk<T>(data: T, init?: ResponseInit): Response {
  return Response.json({ data }, { status: 200, ...init });
}

export async function withApiErrors(
  handler: () => Promise<Response>,
): Promise<Response> {
  try {
    return await handler();
  } catch (error) {
    if (error instanceof ApiError) {
      return Response.json({ error: error.message }, { status: error.status });
    }

    if (error instanceof ZodError) {
      return Response.json(
        { error: "Invalid request", details: error.issues },
        { status: 400 },
      );
    }

    logError("Unhandled API request error", error);
    // Never leak internal error details to the client.
    return Response.json({ error: "Internal server error" }, { status: 500 });
  }
}

export async function parseBody<T>(
  request: Request,
  schema: {
    safeParse: (
      input: unknown,
    ) =>
      | { success: true; data: T }
      | { success: false; error: ZodError };
  },
): Promise<T> {
  let body: unknown;

  try {
    body = await request.json();
  } catch {
    throw new ApiError("Request body must be valid JSON", 400);
  }

  const result = schema.safeParse(body);
  if (!result.success) {
    throw result.error;
  }

  return result.data;
}